    for r, row in enumerate(board):
        for c, letter in enumerate(row):
            for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < len(board) and 0 <= nc < len(board[nr])):
                    continue
                for er, ec in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    tr, tc = nr + er, nc + ec
                    if (tr, tc) == (r, c):
