    best_score = -1
    for r, row in enumerate(board):
        for c, letter in enumerate(row):
            for dr, dc in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                nr, nc = r + dr, c + dc
                if not (0 <= nr < len(board) and 0 <= nc < len(board[nr])):
                    continue
                for er, ec in [(1, 0), (-1, 0), (0, 1), (0, -1)]:
                    tr, tc = nr + er, nc + ec
                    if (tr, tc) == (r, c):
                        continue
                    if 0 <= tr < len(board) and 0 <= tc < len(board[tr]):
                        word = letter + board[nr][nc] + board[tr][tc]
                        score = sum(values[ch] for ch in word)
                        if score > best_score:
                            best, best_score = word, score
    return best
