                    if 0 <= tr < len(board) and 0 <= tc < len(board[tr]):
                        word = letter + board[nr][nc] + board[tr][tc]
                        score = sum(values[ch] for ch in word)
                        if score > best_score:
                            best, best_score = word, score
    return best

